#!/bin/bash
#
#   verify-projects.sh -- Prove the committed makefiles are what the generator produces
#
#   Regenerates projects/gmake2 into a scratch tree and diffs it against the committed files. Any
#   difference is a failure: either someone edited a generated file by hand, or someone changed
#   projects/premake5.lua and did not regenerate.
#
#   Hand edits to a generated file survive until the next regeneration and are then silently reverted.
#   That is how the committed makefiles came to carry 78 lines the generator did not produce, and it is
#   the same mechanism by which a hardening flag added by hand would disappear without a warning.
#
#   Scope is gmake2, which is what every Unix build uses. The vs2022 and xcode outputs are generated by
#   the same premake5.lua and are not checked here: no host in this project builds them, so a diff
#   would report generator-version drift that nobody can act on.
#
#   Usage: bin/verify-projects.sh
#

set -e
unset CDPATH

TOP=$(cd "$(dirname "$0")/.." && pwd)
COMMITTED="$TOP/projects/gmake2"

if ! command -v premake5 >/dev/null 2>&1 ; then
    echo "      [Skip] premake5 not installed - cannot verify the generated makefiles" >&2
    exit 0
fi

SCRATCH=$(mktemp -d "${TMPDIR:-/tmp}/appweb-projects.XXXXXX")
trap 'rm -rf "$SCRATCH"' EXIT

#
#   premake5.lua reads the version from ../package.json, so the scratch tree needs both.
#
mkdir -p "$SCRATCH/projects"
cp "$TOP/package.json" "$SCRATCH/package.json"
cp "$TOP/projects/premake5.lua" "$SCRATCH/projects/premake5.lua"

(cd "$SCRATCH/projects" && premake5 gmake >/dev/null 2>&1) || {
    echo "      [Fail] premake5 could not generate from projects/premake5.lua" >&2
    exit 1
}

if diff -r -u "$SCRATCH/projects/gmake2" "$COMMITTED" > "$SCRATCH/diff" 2>&1 ; then
    echo "      [Info] projects/gmake2 matches the generator"
    exit 0
fi

echo "      [Fail] projects/gmake2 differs from what projects/premake5.lua generates" >&2
echo "" >&2
sed 's/^/               /' "$SCRATCH/diff" >&2
echo "" >&2
echo "               Never edit a generated makefile. Change projects/premake5.lua and run:" >&2
echo "                   cd projects && premake5 gmake" >&2
exit 1
